import{z as s,x as i,o as e,c as l,q as C,j as r,D as a,d as A,s as o,S as t,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"对称加密模式的实践","description":"","frontmatter":{"title":"对称加密模式的实践","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-symmetric-modes.md","filePath":"cs/ce-symmetric-modes.md","lastUpdated":1791063341000}'),c={name:"cs/ce-symmetric-modes.md"};function D(d,E,h,p,m,F){const B=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=C('<h1 id="对称加密模式的实践" tabindex="-1">对称加密模式的实践 <a class="header-anchor" href="#对称加密模式的实践" aria-label="Permalink to &quot;对称加密模式的实践&quot;">​</a></h1><div class="epigraph"><p>选错模式不会让算法变慢，会让它变假：同一个 AES，ECB 里是一台复读机，GCM 里才是一台加密机。</p><footer>—— 据 NIST SP 800-38A、SP 800-38D；Ferguson, Schneier and Kohno, *Cryptography Engineering* 整理</footer></div><p><a href="/cs/dt-case-map">上一课</a>给「分布式事务深化」收束：选型第一问是「能不能单片」，分片键设计优于一切协议优化，性能税等于锁持有、分片数与轮次的乘积。密码学的账更不容含糊：主干<a href="/cs/block-modes">分组模式 CBC / GCM</a>与<a href="/cs/chacha20">ChaCha20</a>给了各模式的名字与密钥流形状。缺口是<strong>选型</strong>：工程里拿到一段要落盘或上链路的明文，第一问不是「用 AES 还是 ChaCha」，而是「用什么模式、nonce 从哪来、完整性谁负责」。本课是「密码学工程」的第一课，把模式选择钉成可执行的规则；后课的 AEAD、签名与协议陷阱都默认这套规则已经在手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模式决定「一块密文依赖哪些输入」。ECB 只依赖本块明文：相同明文块产出相同密文块，图像加密出剪影，这是复读机不是加密。CBC 引入链式依赖与随机 IV，堵住了模式泄露，却添两笔新账：填充使密文对齐块长，而填充校验一旦把失败原因泄露给攻击者，就成了<a href="/cs/padding-oracle">填充预言机</a>的入口；IV 若可预测，首块等价于在攻击者选定的明文下工作。CTR 用计数器编址密钥流，密文长度等于明文长度、可随机访问，但 nonce 唯一性成了硬合同：复用即密钥流复用，两条密文的异或把两段明文的异或直接暴露——与<a href="/cs/one-time-pad-perfect-secrecy">一次一密与完美保密</a>里复用密钥同类的失败。<span class="marginnote">ECB 的失败可以类比成给句子里每个词单独换上同一种固定颜色：内容听不见，但哪些词相同一目了然。著名的「加密企鹅」图就是把企鹅照片逐块 ECB 加密，企鹅轮廓原样可见——这就是「复读机」三字的直观版本。</span>缺口不是再讲一遍这些模式的定义，而是把「谁在什么条件下可用」钉成清单。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践规则按四步走。第一步，任何需要保密的传输或存储，默认选 AEAD：AES-GCM 或 ChaCha20-Poly1305；硬件有 AES 指令选前者，纯软件环境选后者。第二步，nonce 策略随模式定：GCM 的 96 位 nonce 用计数器分配（每密钥一个单调计数器），若只能随机生成，单密钥调用次数必须 \\lt \\(2^{32}\\)，这是 SP 800-38D 把随机 IV 碰撞概率压在 \\(2^{-32}\\) 以下的界；XChaCha20 把 nonce 拉到 192 位，随机生成即可。<span class="marginnote">\\(2^{32}\\) 这条线的来由可以代一下数：生日界下，从 96 位空间里随机取 \\(n\\) 个数，碰撞概率约为 \\(n^2 / 2^{96}\\)。代入 \\(n = 2^{32}\\)，得 \\(2^{64}/2^{96} = 2^{-32}\\)——「可忽略」的门槛正好卡在这里；调用次数再多一个数量级，概率就升到 \\(2^{-12}\\) 量级，工程上不再可忽略。</span>第三步，遗留系统里的 CBC 只能与 HMAC 组合成 Encrypt-then-MAC，且 IV 由 CSPRNG 出、绝不复用；单独 CBC 一律视为错误。第四步，ECB 只允许出现在「单块、明文无结构」的场合，比如作为构造可调 PRP 的零件，永远不直接服务数据。</p>',7)),(e(),r(t,null,{default:a(()=>[o(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E6%9C%89%E6%98%8E%E6%96%87%E8%A6%81%E4%BF%9D%E5%AF%86%22%5D%20--%3E%20Q1%7B%22%E5%AE%8C%E6%95%B4%E6%80%A7%E5%BD%92%E6%9C%AC%E5%B1%82%E7%AE%A1%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20AEAD%5B%22AEAD%EF%BC%9AGCM%20%E6%88%96%20ChaCha20-Poly1305%22%5D%0A%20%20AEAD%20--%3E%20NONCE%5B%22nonce%EF%BC%9A%E8%AE%A1%E6%95%B0%E5%99%A8%E5%88%86%E9%85%8D%E6%88%96%20192%20%E4%BD%8D%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%EF%BC%8C%E9%81%97%E7%95%99%20CBC%7C%20ETM%5B%22CBC%20%2B%20HMAC%EF%BC%8CEncrypt-then-MAC%22%5D%0A%20%20ETM%20--%3E%20IV%5B%22IV%20%E7%94%B1%20CSPRNG%20%E5%87%BA%EF%BC%8C%E7%BB%9D%E4%B8%8D%E5%A4%8D%E7%94%A8%22%5D%0A%20%20NONCE%20--%3E%20OK%5B%22%E5%8F%AF%E4%B8%8A%E7%BA%BF%22%5D%0A%20%20IV%20--%3E%20OK%0A%20%20NEED%20--%3E%20ECB%5B%22ECB%20%E7%9B%B4%E6%8E%A5%E5%8A%A0%E5%AF%86%E6%95%B0%E6%8D%AE%22%5D%0A%20%20ECB%20--%3E%20BAD%5B%22%E7%9B%B8%E5%90%8C%E5%9D%97%E6%B3%84%E9%9C%B2%EF%BC%9A%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[A("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"这些规则的根据是「模式把块密码扩展成语义」的方式。每个模式的安全性证明都按特定前提给出：GCM 的证明要求每 nonce 只用一次，nonce 复用后 GHASH 的认证子密钥 \\(H\\) 会被同 nonce 的标签对恢复，Procter 2014 给出了此后对任意新消息伪造标签的完整路径；CBC 的证明依赖 IV 对攻击者不可预测。反过来说，实践清单的每一条都是在保住证明的前提，而不是风格偏好。长度也要记账：CTR 与 GCM 的密文不膨胀（只多 16 字节标签），CBC 膨胀至多一块且需要填充，落盘格式与去重都因此不同。密钥侧，同一主密钥跨模式使用要过 KDF 并做域分离，否则「CBC 的密钥」与「GCM 的密钥」在证明里是两把，混用等于让两份证明互相作保。",-1)),(e(),r(t,null,{default:a(()=>[o(B,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20N1%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20nonce%20%E5%8A%A0%E5%AF%86%E4%BA%86%E4%B8%A4%E6%9D%A1%E6%B6%88%E6%81%AF%22%5D%20--%3E%20KR%5B%22%E5%AF%86%E9%92%A5%E6%B5%81%E9%87%8D%E5%A4%8D%EF%BC%9A%E4%B8%A4%E6%9D%A1%E5%AF%86%E6%96%87%E5%BC%82%E6%88%96%E5%87%BA%E6%98%8E%E6%96%87%E5%BC%82%E6%88%96%22%5D%0A%20%20N1%20--%3E%20H%5B%22%E4%B8%A4%E6%AC%A1%E6%A0%87%E7%AD%BE%E8%AE%A1%E7%AE%97%E5%85%B1%E7%94%A8%E5%90%8C%E4%B8%80%E4%B8%AA%E8%AE%A4%E8%AF%81%E5%AD%90%E5%AF%86%E9%92%A5%20H%22%5D%0A%20%20H%20--%3E%20REC%5B%22%E6%A0%87%E7%AD%BE%E5%AF%B9%E6%8A%8A%20H%20%E6%81%A2%E5%A4%8D%E5%87%BA%E6%9D%A5%22%5D%0A%20%20REC%20--%3E%20FORG%5B%22%E5%8F%AF%E5%AF%B9%E4%BB%BB%E6%84%8F%E6%96%B0%E6%B6%88%E6%81%AF%E4%BC%AA%E9%80%A0%E6%A0%87%E7%AD%BE%22%5D%0A%20%20FORG%20--%3E%20DEAD%5B%22%E4%BF%9D%E5%AF%86%E4%B8%8E%E5%AE%8C%E6%95%B4%E6%80%A7%E5%90%8C%E6%97%B6%E5%A4%B1%E5%AE%88%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=C('<p><span class="marginnote">「AEAD」翻译过来是「带关联数据的认证加密」：加密（保密）、认证（防篡改）、关联数据（不加密但同样不许被改的头部，比如路由地址）三件事一次合同做完。它把「先加密再 MAC 还是先 MAC 再加密」这种最容易做错的组合决策从使用者手里收走——这正是本课默认选它的理由。</span></p><p><span class="marginnote">SP 800-38D 的两道账：单密钥总加密量不超过 \\(2^{39}-256\\) 比特（约 64 GiB）；随机 96 位 IV 时调用次数不超过 \\(2^{32}\\)。任一越界，GHASH 的认证优势就按生日界塌掉——大吞吐服务在同一密钥下写满一年数据，恰好会撞线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只管「加密模式怎么选」，nonce 复用之后 AEAD 内部发生什么属于下一课；完整性合同与标签语义在 <a href="/cs/aead-gcm-internals">AEAD 与 GCM 内部</a>已钉。XTS 这类宽块可调模式服务磁盘扇区（SP 800-38E），只给扇区级保密、不给完整性，不在本课清单里，也不该被当成 AEAD 用。密钥怎么生成、熵从哪来，是「随机数」课的缺口；协议层组合错误（重放、降级、预言机）留给「协议实现的陷阱」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模式选择的第一问是完整性归谁：本层管就用 AEAD，遗留 CBC 必配 HMAC。</li><li>GCM 的 nonce 用计数器分配；只能随机时，单密钥调用次数 \\lt \\(2^{32}\\)。</li><li>ECB 不直接服务数据；CTR nonce 复用与一次一密复用密钥同类失败。</li><li>IV 可预测、nonce 复用、无 MAC 的 CBC，都是证明前提被打破的三种形状。</li><li>出处：NIST SP 800-38A/38D；RFC 8439；Ferguson, Schneier and Kohno, <em>Cryptography Engineering</em>；Procter 2014。</li></ul>',6))])}const P=s(c,[["render",D]]);export{f as __pageData,P as default};
